export async function creditPlay({ db, nowS }, playerId) {
  const was = await db.prepare('SELECT played_at FROM players WHERE id = ?').bind(playerId).first();
  const gap = Number.isSafeInteger(was?.played_at) ? nowS - was.played_at : -1;
  await db.prepare('UPDATE players SET played_s = played_s + ?, played_at = MAX(COALESCE(played_at, 0), ?) WHERE id = ?').bind(gap > 0 && gap <= PLAY_GRACE_S ? gap : 0, nowS, playerId).run();
  if (playerId) return { playedS: (await db.prepare('SELECT played_s FROM players WHERE id = ?').bind(playerId).first()).played_s };
